#include "jit.hpp"
#include <algorithm>
#include <chrono>
#include <iostream>
#include <stdexcept>
using namespace pc;
int main(int argc,char **argv) {
 try {
  unsigned loops=argc>1?std::stoul(argv[1]):1000000;
  bool enabled=argc<3 || std::string(argv[2])!="interpreter";
  if(!loops || loops>10000000) throw std::runtime_error("Invalid loop count");
  std::cout << "[";
  bool first=true;
  for(bool code32:{false,true}) for(bool stack32:{false,true}) for(bool paging:{false,true}) {
   CPU c(1024*1024);
   c.cr[0]=0x11;
   c.s[CS].big=code32; c.s[CS].limit=code32?UINT32_MAX:65535;
   c.s[SS].big=stack32; c.s[SS].base=0x10000; c.s[SS].limit=UINT32_MAX;
   c.r[AX]=0x100; c.r[CX]=loops; c.r[DX]=0; c.r[SP]=0x7000;
   c.write(0x4000,3,code32?4:2);
   std::vector<uint8_t> code=code32 ? std::vector<uint8_t>{0xff,0x35,0,0x40,0,0,0x5a,0x01,0xd3}
                                     : std::vector<uint8_t>{0xff,0x36,0,0x40,0x5a,0x01,0xd3};
   if(!code32) code.push_back(0x66);
   code.insert(code.end(),{0x83,0xe9,1,0x75,uint8_t(-int(code.size()+5))});
   auto end=code.size(); code.push_back(0xf4);
   std::copy(code.begin(),code.end(),c.mem.begin());
   c.mem[0x100]=0x83;c.mem[0x101]=0xc2;c.mem[0x102]=1;c.mem[0x103]=0xc3;
   if(paging) {
    c.write(0x80000,0x81007,4);
    for(unsigned p=0;p<256;++p)c.write(0x81000+4*p,(p<<12)|7,4);
    c.cr[3]=0x80000;c.cr[0]|=0x80000000;c.flushTLB();
   }
   Jit jit(c,enabled);
   auto start=std::chrono::steady_clock::now();
   while(c.ip!=end && c.instructions<=uint64_t(loops)*5)jit.run();
   double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();
   if(c.ip!=end || c.r[CX] || c.r[BX]!=(code32?loops*3:(loops*3)&65535) || c.r[DX]!=3 || c.r[SP]!=0x7000 || c.instructions!=uint64_t(loops)*5)
    throw std::runtime_error("PUSH/POP count, stack, destination or checksum mismatch");
   if(!first)std::cout << ",";first=false;
   std::cout << "{\"code32\":"<<code32<<",\"stack32\":"<<stack32<<",\"paging\":"<<paging<<",\"loops\":"<<loops<<",\"instructions\":"<<c.instructions<<",\"native\":"<<jit.nativeInstructions<<",\"checksum\":"<<c.r[BX]<<",\"seconds\":"<<sec<<"}"<<std::flush;
  }
  std::cout << "]\n";
 }catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}
}

