#include "jit.hpp"
#include <algorithm>
#include <iostream>
using namespace pc;
static unsigned checks;
static void check(bool v,const char*s){++checks;if(!v)throw std::runtime_error(s);}
static void equal(const CPU&a,const CPU&b){check(a.ip==b.ip&&a.flags==b.flags&&a.instructions==b.instructions,"context IP/flags/count");check(std::equal(std::begin(a.r),std::end(a.r),std::begin(b.r)),"context GPRs");check(a.mem==b.mem&&a.cr[2]==b.cr[2],"context RAM/CR2");}
static void batch(Jit&j,CPU&c,CPU&ref){auto r=j.runBatch();check(r.instructions&&r.instructions<=127,"context progress/budget");for(unsigned i=0;i<r.instructions;++i)ref.step();equal(c,ref);}
int main(){try{
 for(unsigned mutation=0;mutation<11;++mutation){
  CPU c(2*1024*1024);c.cr[0]=0x11;c.s[CS].big=c.s[SS].big=true;c.r[SP]=0x9000;c.r[CX]=10000;
  const uint8_t code[]={0x83,0xc0,1,0xeb,3,0x90,0x90,0x90,0x50,0x5a,0x83,0xe9,1,0x75,0xf1};
  std::copy(std::begin(code),std::end(code),c.mem.begin());std::copy(std::begin(code),std::end(code),c.mem.begin()+0x100000);
  if(mutation==5)c.s[CS].base=0x100000;
  CPU ref=c;Jit j(c,true,0,65536);for(unsigned i=0;i<4;++i)batch(j,c,ref);
  unsigned writes=0,refWrites=0;auto before=j.compiledBlocks;
  for(CPU*p:{&c,&ref}){
   p->ip=0;p->r[CX]=10000;
   switch(mutation){
   case 0:++p->executionEpoch;break;
   case 1:p->cr[0]^=0x10000;break;
   case 2:p->cr[3]=0x180000;p->flushTLB();break;
   case 3:p->s[CS].base=0x100000;break;
   case 4:p->flags^=0x20000;break;
   case 5:p->a20=false;break;
   case 6:p->s[SS].big=false;break;
   case 7:{auto copy=p->mem;p->mem.swap(copy);break;}
   case 8:p->mem.resize(1024*1024);p->r[SP]=0x100008;break;
   case 9:{auto copy=p->codeUsed;p->codeUsed.swap(copy);break;}
   case 10:p->watchStart=0x8000;p->watchLength=0x2000;p->watchWrite=p==&c?std::function<void(uint32_t,uint32_t,int)>([&](uint32_t,uint32_t,int){++writes;}):std::function<void(uint32_t,uint32_t,int)>([&](uint32_t,uint32_t,int){++refWrites;});break;
   }
  }
  for(unsigned i=0;i<5;++i)batch(j,c,ref);
  check(j.compiledBlocks>=before+(mutation==6?1:2),"stale context failed to rebuild cached blocks");
  if(mutation==10)check(writes&&writes==refWrites,"context skipped watched writes");
 }
 // Code generation still changes even when the invariant CPU context is identical.
 {
  CPU c(65536);c.s[CS].big=true;c.r[CX]=10000;const uint8_t code[]={0x83,0xc0,1,0x83,0xe9,1,0x75,0xf8};std::copy(std::begin(code),std::end(code),c.mem.begin());CPU ref=c;Jit j(c,true,0,65536);for(unsigned i=0;i<3;++i)batch(j,c,ref);c.ip=ref.ip=0;c.write(2,3,1);ref.write(2,3,1);auto before=j.compiledBlocks;batch(j,c,ref);check(j.compiledBlocks>before,"context suppressed code generation invalidation");
 }
 // Current fetch translations and permissions remain mandatory after a TLB flush.
 for(bool deny:{false,true}){
  CPU c(1024*1024);c.cr[0]=0x11;c.cr[3]=0x80000;c.s[CS].big=true;c.s[CS].selector=3;c.r[CX]=10000;c.write(0x80000,0x81007,4);for(unsigned i=0;i<256;++i)c.write(0x81000+4*i,(i<<12)|7,4);c.cr[0]|=0x80000000;c.flushTLB();
  const uint8_t first[]={0x83,0xc0,1,0xe9,0xf8,0x3f,0,0};std::copy(std::begin(first),std::end(first),c.mem.begin());
  const uint8_t second[]={0x83,0xc3,1,0xe9,0xf8,0xbf,0xff,0xff};std::copy(std::begin(second),std::end(second),c.mem.begin()+0x4000);std::copy(std::begin(second),std::end(second),c.mem.begin()+0x5000);c.mem[0x5002]=3;
  CPU ref=c;Jit j(c,true,0,65536);for(unsigned i=0;i<4;++i)batch(j,c,ref);
  for(CPU*p:{&c,&ref}){p->ip=0;p->write(0x81010,deny?0x4003:0x5007,4);p->flushTLB();}
  if(!deny)batch(j,c,ref);
  else{struct Stop{};unsigned a=0,b=0;ref.observeFault=[&](const Fault&f){check(f.vector==14&&f.error==5,"reference fetch fault");++a;throw Stop{};};c.observeFault=[&](const Fault&f){check(f.vector==14&&f.error==5,"cached context fetch fault");++b;throw Stop{};};try{ref.step();ref.step();ref.step();}catch(const Stop&){}try{j.runBatch();}catch(const Stop&){}equal(c,ref);check(a==1&&b==1&&c.ip==0x4000&&c.cr[2]==0x4000,"context bypassed fetch permission");}
 }
 // Public single-block dispatch between batches cannot lend an invalid context stamp.
 {
  CPU c(65536);c.cr[0]=0x11;c.s[CS].big=true;c.r[CX]=10000;const uint8_t code[]={0x83,0xc0,1,0x83,0xe9,1,0x75,0xf8};std::copy(std::begin(code),std::end(code),c.mem.begin());CPU ref=c;Jit j(c,true,0,65536);for(unsigned i=0;i<3;++i)batch(j,c,ref);
  for(unsigned i=0;i<40;++i){c.ip=ref.ip=0;c.cr[0]^=0x10000;ref.cr[0]^=0x10000;auto n=j.run();for(unsigned k=0;k<n;++k)ref.step();equal(c,ref);c.cr[0]^=0x10000;ref.cr[0]^=0x10000;batch(j,c,ref);if(i%5==0)j.clear();}
 }
 std::cout<<"Passed "<<checks<<" context mutation checks\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
